"""Робот edu, 14.11 (двадцать восьмой запуск): выдачи Яндекс Карт по районам → auto/fetch-queue.txt (ключи eu<N>-1138e, «Особым детям» по городу — eu<N>-1138f).
Районы — 15, где робот edu не искал дольше всего (12.11): 9 станций метро + 6 городов Подмосковья. На район: 3 запроса «Особым детям» + 3 по направлениям
(упор на новые: сады, чтение, математика, ментальная арифметика, программирование, лего)."""
import json, os, urllib.parse
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
METRO = ["Локомотив", "Лубянка", "Лужники", "Лухмановская", "Марксистская", "Менделеевская", "Минская", "Митино", "Мичуринский проспект"]
TOWNS = ["Клин", "Егорьевск", "Наро-Фоминск", "Ивантеевка", "Дзержинский", "Солнечногорск"]
INC = ["инклюзивный центр для детей", "занятия для детей с ОВЗ", "адаптивная физкультура для детей", "занятия для детей с аутизмом",
       "сенсорная комната для детей", "центр для детей с РАС", "адаптивное плавание для детей", "инклюзивная студия для детей",
       "коррекционный центр для детей", "дефектолог для детей", "АВА-терапия для детей", "нейропсихолог для детей", "центр для детей с синдромом Дауна",
       "сенсорная интеграция для детей", "занятия для детей с ДЦП", "центр для особых детей"]
TH = ["программирование для детей", "лего конструирование для детей", "частный детский сад", "скорочтение для детей", "математический кружок для детей",
      "ментальная арифметика", "обучение чтению детей", "монтессори", "логопед для детей", "ЛФК для детей", "детский психолог",
      "робототехника для детей", "подготовка к школе", "центр раннего развития", "английский для детей", "каллиграфия для детей", "детский массаж",
      "курсы программирования Python для детей", "мини-сад"]
Q = []
for i, a in enumerate(METRO + TOWNS):
    w = f"метро {a}" if a in METRO else a
    k = i + 9
    for t in (INC[(3 * k) % len(INC)], INC[(3 * k + 1) % len(INC)], INC[(3 * k + 2) % len(INC)], TH[(3 * k) % len(TH)], TH[(3 * k + 1) % len(TH)], TH[(3 * k + 2) % len(TH)]):
        Q.append(f"{t} {w}")
Q2 = ["иппотерапия для детей Подмосковье", "конный центр иппотерапия для детей с ОВЗ Москва", "адаптивное плавание для детей с инвалидностью Москва",
      "инклюзивная театральная студия для детей Москва", "занятия для детей с синдромом Дауна Подмосковье", "центр для детей с аутизмом Балашиха",
      "инклюзивный центр для детей Мытищи", "инклюзивный центр для детей Одинцово", "центр для детей с аутизмом Щёлково", "занятия для детей с ОВЗ Видное",
      "адаптивная физкультура для детей Новая Москва", "сенсорная комната для детей Зеленоград", "ментальная арифметика Балашиха", "скорочтение для детей Мытищи",
      "частный детский сад Одинцово", "программирование для детей Щёлково", "лего студия для детей Подольск", "математический кружок для детей Москва",
      "каллиграфия для детей Подмосковье", "частный детский сад Красногорск", "школа программирования для детей Зеленоград", "лего конструирование для детей Химки"]
if __name__ == "__main__":
    urls = [f"https://yandex.ru/maps/1/moscow-and-moscow-oblast/?eu{n}=1138e&text=" + urllib.parse.quote(q) for n, q in enumerate(Q)]
    urls += [f"https://yandex.ru/maps/1/moscow-and-moscow-oblast/?eu{n}=1138f&text=" + urllib.parse.quote(q) for n, q in enumerate(Q2)]
    old = open(os.path.join(ROOT, "auto/fetch-queue.txt")).read()
    open(os.path.join(ROOT, "auto/fetch-queue.txt"), "w").write("\n".join(urls) + "\n" + old)
    json.dump(Q, open(os.path.join(ROOT, "tools/edu_1138_queries.json"), "w"), ensure_ascii=False, indent=0)
    json.dump(Q2, open(os.path.join(ROOT, "tools/edu_1138_queries2.json"), "w"), ensure_ascii=False, indent=0)
    print(len(urls))
